// INPUT: Stable schemas generated by an official CLI in an empty temporary home.
// OUTPUT: A bounded, read-only check that explicit and idempotent redemption exists.
// POS: Transport capability gate; see CodexTransport/README.md. Never redeems a credit.
import Foundation
import Darwin
import RuneCore

private let capabilityMethod = "account/rateLimitResetCredit/consume"
private let capabilityOutcomes: Set<String> = ["reset", "nothingToReset", "noCredit", "alreadyRedeemed"]

/// This checks the wire contract, not backend redemption eligibility. The caller
/// caches success only for the executable fingerprint that was checked.
func verifyConsumeCapability(executable: String, timeoutMs: Int = 5_000) async throws {
    try await withCheckedThrowingContinuation { continuation in
        DispatchQueue.global(qos: .utility).async {
            do {
                let root = FileManager.default.temporaryDirectory.appendingPathComponent("reset-rune-capability-" + UUID().uuidString)
                try FileManager.default.createDirectory(at: root, withIntermediateDirectories: false, attributes: [.posixPermissions: 0o700])
                defer { try? FileManager.default.removeItem(at: root) }
                let home = root.appendingPathComponent("home"), codex = root.appendingPathComponent("codex")
                let schemas = root.appendingPathComponent("schemas"), temporary = root.appendingPathComponent("tmp")
                for directory in [home, codex, schemas, temporary] {
                    try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: false, attributes: [.posixPermissions: 0o700])
                }
                let process = Process()
                process.executableURL = URL(fileURLWithPath: executable)
                process.arguments = ["app-server", "generate-json-schema", "--out", schemas.path]
                process.currentDirectoryURL = root
                process.environment = ["HOME": home.path, "CODEX_HOME": codex.path, "TMPDIR": temporary.path, "PATH": "/usr/bin:/bin"]
                process.standardInput = FileHandle.nullDevice
                process.standardOutput = FileHandle.nullDevice
                process.standardError = FileHandle.nullDevice
                try process.run()
                let timeout = DispatchWorkItem { if process.isRunning { kill(process.processIdentifier, SIGKILL) } }
                DispatchQueue.global(qos: .utility).asyncAfter(deadline: .now() + .milliseconds(max(1, timeoutMs)), execute: timeout)
                defer { timeout.cancel(); if process.isRunning { kill(process.processIdentifier, SIGKILL); process.waitUntilExit() } }
                process.waitUntilExit()
                guard process.terminationStatus == 0 else { throw incompatibleCapability() }
                try validateConsumeCapability(in: schemas)
                continuation.resume()
            } catch {
                // CLI output and filesystem errors can contain private paths.
                continuation.resume(throwing: incompatibleCapability())
            }
        }
    }
}

private func incompatibleCapability() -> RuneError { RuneError("runtime-incompatible", notSent: true) }

func validateConsumeCapability(in directory: URL) throws {
    // Generated schemas are data, never imports. No symlinks or external refs
    // may turn this check into an authentication or arbitrary file read.
    var files = 0, bytes: Int64 = 0
    guard let entries = FileManager.default.enumerator(at: directory, includingPropertiesForKeys: nil) else { throw incompatibleCapability() }
    for case let file as URL in entries {
        files += 1
        var info = stat()
        guard files <= 1_024, lstat(file.path, &info) == 0, info.st_uid == getuid(),
              info.st_mode & S_IFMT == S_IFREG || info.st_mode & S_IFMT == S_IFDIR else { throw incompatibleCapability() }
        if info.st_mode & S_IFMT == S_IFREG {
            guard info.st_size <= 4 * 1024 * 1024 else { throw incompatibleCapability() }
            bytes += info.st_size
            guard bytes <= 16 * 1024 * 1024 else { throw incompatibleCapability() }
        }
    }
    func load(_ relative: String) throws -> JSONObject {
        let path = directory.appendingPathComponent(relative)
        let fd = open(path.path, O_RDONLY | O_NOFOLLOW | O_NONBLOCK)
        guard fd >= 0 else { throw incompatibleCapability() }
        defer { Darwin.close(fd) }
        var info = stat()
        guard fstat(fd, &info) == 0, info.st_mode & S_IFMT == S_IFREG, info.st_uid == getuid(),
              info.st_size > 0, info.st_size <= 4 * 1024 * 1024 else { throw incompatibleCapability() }
        let handle = FileHandle(fileDescriptor: fd, closeOnDealloc: false)
        guard let data = try? handle.read(upToCount: 4 * 1024 * 1024 + 1), data.count <= 4 * 1024 * 1024,
              let object = (try? JSONSerialization.jsonObject(with: data)) as? JSONObject else { throw incompatibleCapability() }
        return object
    }
    let request = try load("ClientRequest.json")
    guard let branches = request["oneOf"] as? [JSONObject] else { throw incompatibleCapability() }
    var matched = false
    for branch in branches {
        let properties = try resolveCapabilityNode(branch, root: request)["properties"] as? JSONObject
        guard let method = properties?["method"] as? JSONObject,
              let values = try resolveCapabilityNode(method, root: request)["enum"] as? [String], values.contains(capabilityMethod) else { continue }
        guard !matched, let paramsNode = properties?["params"] as? JSONObject else { throw incompatibleCapability() }
        let params = try resolveCapabilityNode(paramsNode, root: request)
        guard params["type"] as? String == "object", let fields = params["properties"] as? JSONObject,
              let credit = fields["creditId"] as? JSONObject,
              let key = fields["idempotencyKey"] as? JSONObject,
              try capabilityAllowsString(credit, root: request), try capabilityAllowsString(key, root: request),
              let required = params["required"] as? [String], required.contains("idempotencyKey"),
              Set(required).isSubset(of: ["creditId", "idempotencyKey"]) else { throw incompatibleCapability() }
        matched = true
    }
    guard matched else { throw incompatibleCapability() }
    let response = try load("v2/ConsumeAccountRateLimitResetCreditResponse.json")
    guard let properties = response["properties"] as? JSONObject,
          let outcome = properties["outcome"] as? JSONObject,
          let required = response["required"] as? [String], required.contains("outcome"),
          capabilityOutcomes.isSubset(of: try capabilityStringValues(outcome, root: response)) else { throw incompatibleCapability() }
}

private func resolveCapabilityNode(_ input: JSONObject, root: JSONObject, depth: Int = 0) throws -> JSONObject {
    guard depth < 12 else { throw incompatibleCapability() }
    guard let reference = input["$ref"] else { return input }
    guard let reference = reference as? String, reference.hasPrefix("#/"), !reference.contains("%") else { throw incompatibleCapability() }
    var current: Any = root
    for part in reference.dropFirst(2).split(separator: "/", omittingEmptySubsequences: false) {
        let key = String(part).replacingOccurrences(of: "~1", with: "/").replacingOccurrences(of: "~0", with: "~")
        guard let dictionary = current as? JSONObject, let next = dictionary[key] else { throw incompatibleCapability() }
        current = next
    }
    guard let node = current as? JSONObject else { throw incompatibleCapability() }
    return try resolveCapabilityNode(node, root: root, depth: depth + 1)
}

private func capabilityAllowsString(_ input: JSONObject, root: JSONObject, depth: Int = 0) throws -> Bool {
    guard depth < 12 else { throw incompatibleCapability() }
    let node = try resolveCapabilityNode(input, root: root)
    if node["type"] as? String == "string" { return true }
    if let types = node["type"] as? [String], types.contains("string") { return true }
    for key in ["oneOf", "anyOf"] {
        if let options = node[key] as? [JSONObject] {
            for option in options where try capabilityAllowsString(option, root: root, depth: depth + 1) { return true }
        }
    }
    return false
}

private func capabilityStringValues(_ input: JSONObject, root: JSONObject, depth: Int = 0) throws -> Set<String> {
    guard depth < 12 else { throw incompatibleCapability() }
    let node = try resolveCapabilityNode(input, root: root)
    var result = Set<String>()
    if node["type"] as? String == "string", let values = node["enum"] as? [String] { result.formUnion(values) }
    for key in ["oneOf", "anyOf"] {
        if let options = node[key] as? [JSONObject] {
            for option in options { result.formUnion(try capabilityStringValues(option, root: root, depth: depth + 1)) }
        }
    }
    return result
}
